$ErrorActionPreference = 'Stop'
$repoRoot = Split-Path $PSScriptRoot -Parent
. (Join-Path $PSScriptRoot 'assert_native_architecture.ps1')
$source = Join-Path $repoRoot '.deps/dxvk-remix'
. (Join-Path $source 'bridge/build_common.ps1')
SetupVS -Platform 'x86' -VcVarsVer '14.29'
$testDir = Join-Path $repoRoot '.deps/steam-web-test'
New-Item -ItemType Directory -Force $testDir | Out-Null
Push-Location $testDir
try {
  & cl.exe /nologo /std:c++17 /EHsc /O2 /W4 /WX "/I$source/bridge/src/util" "$repoRoot/tests/steam_web_diagnostics.cpp" /Fe:web-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Web diagnostic compilation failed' }
  Assert-NativeArchitecture -Path (Join-Path $testDir 'web-test.exe') -Architecture 'x86'
  & .\web-test.exe
  if ($LASTEXITCODE -ne 0) { throw 'Web diagnostic ABI/observation tests failed' }
} finally { Pop-Location }
